"""Seed SQL for a generic pilot family. NOT APPLIED. Usage: python3 gen_family_seed.py <slug> <migration-timestamp> [quran-links-json]"""
import json,hashlib,sys,re
from build_family import norm
slug,ts=sys.argv[1],sys.argv[2]; QL=json.loads(sys.argv[3]) if len(sys.argv)>3 else []
P='/workspace/qsp-hce/hadith-engine/pilot/'
fam=json.load(open(P+slug+'.json'));an=json.load(open(P+slug+'.analysis.json'));cc=json.load(open(P+slug+'.conclusions.json'))
q=lambda v:'null' if v is None else ("'"+str(v).replace("'","''")+"'")
F=f"(select id from public.hadith_families where slug={q(slug)})"
MID=lambda cid:f"(select id from public.hadith_family_members where family_id={F} and hadith_corpus_canonical_id={cid})"
L=[f"-- Seed: pilot family '{slug}'. NOT APPLIED. Requires owner approval.",
   "-- Generated by gen_family_seed.py from hadith-engine/pilot/%s*.json. Idempotent (on conflict do nothing). Depends on 20261103120000_hadith_comparison_engine_schema.sql."%slug,
   "-- Isnad transmitter keys are auto-extracted Arabic name chunks (identity_status candidate).","begin;",
   f"insert into public.hadith_families(slug,title,family_type,scope,narrative_group_id,verification_status,created_by,method) values ({q(slug)},{q(fam['title'])},{q(fam['family_type'])},{q(fam['scope'])},{fam['narrative_group_id'] if fam['narrative_group_id'] else 'null'},'source_checked','grok-bot','hce-rules-v1') on conflict (slug) do nothing;"]
for k,t in fam['transmitters'].items():
    L.append(f"insert into public.hadith_transmitters(key,display_name,arabic_pattern,generation_role) values ({q(k)},{q(t['name'])},{q(t['arabic_pattern'])},{q(t['role'])}) on conflict (key) do nothing;")
for p,lab in fam['propositions'].items():
    L.append(f"insert into public.hadith_family_propositions(family_id,key,label) values ({F},{q(p)},{q(lab)}) on conflict do nothing;")
for m in fam['members']:
    cid=m['hadith_corpus_canonical_id']; h=hashlib.sha256(norm(m['text_arabic']).encode()).hexdigest()
    L.append(f"insert into public.hadith_family_members(family_id,hadith_corpus_canonical_id,branch,is_abridged,text_norm_sha256,membership_status,membership_evidence) values ({F},{cid},{q(m['branch'])},{str(m['abridged']).lower()},{q(h)},'source_checked',{q('full-text match to '+m['verified_url']+' ratio '+str(m['text_match_ratio']))}) on conflict do nothing;")
    L.append(f"insert into public.hadith_variants(hadith_corpus_canonical_id,edition,reference,url,match_method,match_ratio,verified_at,verification_status) values ({cid},'sunnah.com',{q(m['verified_reference'])},{q(m['verified_url'])},'full_text_normalised',{m['text_match_ratio']},'2026-11-03T21:00:00Z','source_checked') on conflict do nothing;")
    L.append(f"insert into public.hadith_variants(hadith_corpus_canonical_id,edition,reference,url,match_method,verification_status) values ({cid},'qh_stored_number',{q(m['collection']+' '+m['db_hadith_number'])},null,'as_stored',{q('disputed' if m['url_mismatch'] else 'source_checked')}) on conflict do nothing;")
    for i,route in enumerate(m['isnad_routes'],1):
        L.append(f"insert into public.hadith_isnads(member_id,route_no,note) values ({MID(cid)},{i},{q(m.get('isnad_note') or 'auto-extracted (candidate)')}) on conflict do nothing;")
        seen=set()
        for j,t in enumerate(route,1):
            L.append(f"insert into public.hadith_isnad_links(isnad_id,position,transmitter_id,inherited) values ((select id from public.hadith_isnads where member_id={MID(cid)} and route_no={i}),{j},(select id from public.hadith_transmitters where key={q(t)}),false) on conflict do nothing;")
    for p,c in m['claims'].items():
        L.append(f"insert into public.hadith_proposition_assertions(proposition_id,member_id,stance,value,exclusive,lexical,interpretation,evidence_arabic,verification_status) values ((select id from public.hadith_family_propositions where family_id={F} and key={q(p)}),{MID(cid)},'affirms',{q(c.get('value'))},{str(bool(c.get('exclusive'))).lower()},{str(bool(c.get('lexical'))).lower()},{q(c.get('interpretation'))},{q(c['evidence'])},'candidate') on conflict do nothing;")
r2c={m['verified_reference']:m['hadith_corpus_canonical_id'] for m in fam['members']}
for r in an['relationships']:
    L.append(f"insert into public.hadith_relationships(family_id,member_a_id,member_b_id,relationship,layer,similarity,differences,method) values ({F},{MID(r2c[r['a']])},{MID(r2c[r['b']])},{q(r['label'])},'matn',{r['similarity']},{q(json.dumps(r['differences'],ensure_ascii=False))}::jsonb,'hce-rules-v1') on conflict do nothing;")
for i,c in enumerate(cc['conclusions'],1):
    L.append(f"insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ({F},'conclusion',{i},{q(c['text'])},array[{','.join(q(x) for x in c['citations'])}]::text[],'grok-bot') on conflict do nothing;")
for i,u in enumerate(cc['uncertainties'],1):
    L.append(f"insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ({F},'uncertainty',{i},{q(u)},'grok-bot') on conflict do nothing;")
for s,a,b,rel,ev,cid in QL:
    L.append(f"insert into public.hadith_quran_links(family_id,sura_id,aya_from,aya_to,relation,evidence_member_id,evidence_arabic,verification_status) values ({F},{s},{a},{b},{q(rel)},{MID(cid) if cid else 'null'},{q(ev)},{q('source_checked' if rel=='quoted_in_text' else 'candidate')}) on conflict do nothing;")
L.append("commit;")
out=f'/workspace/qsp-hce/supabase/migrations/{ts}_hadith_family_seed_{slug.replace("-","_")}.sql'
open(out,'w').write('\n'.join(L)+'\n'); print(out,len(L))
